"proven":{a:[{tr:"s. kanıtlanmış, ispatlanmış",ex:"Vaccination remains the most proven method for preventing the spread of many infectious diseases.",exTr:"Aşılama, birçok bulaşıcı hastalığın yayılmasını önlemek için en kanıtlanmış yöntem olmaya devam ediyor."}],kl:[{en:"a proven track record",tr:"kanıtlanmış bir geçmiş başarı"},{en:"scientifically proven",tr:"bilimsel olarak kanıtlanmış"}]},
