"suitable":{a:[{tr:"s. uygun, elverişli",ex:"Researchers are searching for a suitable location to build the new observatory.",exTr:"Araştırmacılar, yeni gözlemevini inşa etmek için uygun bir konum arıyor."}],kl:[{en:"suitable for sth",tr:"bir şeye uygun"},{en:"suitable for children",tr:"çocuklar için uygun"},{en:"a suitable candidate",tr:"uygun bir aday"}]},
"tackle":{a:[{tr:"f. ele almak, üstesinden gelmek",ex:"Governments worldwide are developing new policies to tackle the growing problem of plastic pollution.",exTr:"Dünya genelindeki hükümetler, artan plastik kirliliği sorununun üstesinden gelmek için yeni politikalar geliştiriyor.",yz:4},{tr:"i. donanım, takım",ex:"The fisherman kept all his tackle neatly organized in a large wooden box by the door.",exTr:"Balıkçı, tüm donanımını kapının yanındaki büyük ahşap kutuda düzenli bir şekilde tutuyordu.",yz:1}],es:"address, deal with",kl:[{en:"tackle a problem",tr:"bir sorunla uğraşmak"},{en:"tackle climate change",tr:"iklim değişikliğiyle mücadele etmek"}]},
