"electric":{a:[{tr:"s. elektrikli, elektrik",ex:"Sales of electric cars have risen sharply as battery prices continue to fall.",exTr:"Batarya fiyatları düşmeye devam ederken elektrikli otomobil satışları keskin biçimde arttı.",yz:4},{tr:"i. elektrikli taşıt",ex:"Half the city's bus fleet has already been replaced with electrics.",exTr:"Kentin otobüs filosunun yarısı çoktan elektriklilerle değiştirildi.",yz:1}],kl:[{en:"an electric car",tr:"elektrikli araç"},{en:"an electric shock",tr:"elektrik çarpması"}]},
"error":{a:[{tr:"hata, yanlışlık",ex:"A small measurement error can lead to serious problems in engineering projects.",exTr:"Küçük bir ölçüm hatası, mühendislik projelerinde ciddi sorunlara yol açabilir."}],kl:[{en:"trial and error",tr:"deneme yanılma"},{en:"a margin of error",tr:"hata payı"}]},
"fruit":{a:[{tr:"i. meyve",ex:"Nutritionists recommend eating a variety of fruit every day for essential vitamins.",exTr:"Beslenme uzmanları, gerekli vitaminler için her gün çeşitli meyveler yemeyi önerir.",yz:4},{tr:"f. meyve vermek",ex:"In unusually warm years, these apple trees fruit several weeks earlier than expected.",exTr:"Alışılmadık derecede sıcak yıllarda bu elma ağaçları beklenenden birkaç hafta erken meyve verir.",yz:1}],kl:[{en:"bear fruit",tr:"meyve vermek, sonuç vermek"},{en:"the fruits of sth",tr:"bir şeyin meyveleri"},{en:"fresh fruit",tr:"taze meyve"}]},
