"scope":{a:[{tr:"i. kapsam, alan",ex:"The committee decided to broaden the scope of its investigation into the chemical spill.",exTr:"Komite, kimyasal sızıntıyla ilgili soruşturmasının kapsamını genişletmeye karar verdi.",yz:4},{tr:"i. olanak",ex:"Managers believe there is still considerable scope for improving efficiency on the factory floor.",exTr:"Yöneticiler, fabrika zemininde verimliliği artırmak için hâlâ önemli bir olanak olduğuna inanıyor.",yz:2}],kl:[{en:"the scope of sth",tr:"bir şeyin kapsamı"},{en:"beyond the scope of",tr:"kapsamının dışında"},{en:"scope for improvement",tr:"gelişme olanağı"}]},
"significance":{a:[{tr:"i. önem; anlam",ex:"Archaeologists debated the historical significance of the newly discovered inscriptions for several months.",exTr:"Arkeologlar, yeni keşfedilen yazıtların tarihsel önemini aylarca tartıştı."}],kl:[{en:"the significance of sth",tr:"bir şeyin önemi"},{en:"attach significance to sth",tr:"bir şeye önem atfetmek"},{en:"of great significance",tr:"büyük önem taşıyan"}]},
"treaty":{a:[{tr:"i. antlaşma",ex:"The two nations signed a treaty aimed at reducing carbon emissions over the next decade.",exTr:"İki ulus, önümüzdeki on yılda karbon emisyonlarını azaltmayı amaçlayan bir antlaşma imzaladı."}],kl:[{en:"sign a treaty",tr:"antlaşma imzalamak"},{en:"a peace treaty",tr:"barış antlaşması"}]},
"beautiful":{a:[{tr:"s. güzel",ex:"Tourists travel thousands of kilometers to see the beautiful landscapes of New Zealand.",exTr:"Turistler, Yeni Zelanda'nın güzel manzaralarını görmek için binlerce kilometre yol kat eder."}]},
"count":{a:[{tr:"f. saymak",ex:"The teacher asked the young children to count the number of birds visible in the schoolyard.",exTr:"Öğretmen, küçük çocuklardan okul bahçesinde görünen kuşların sayısını saymalarını istedi.",yz:4},{tr:"f. önemli olmak",ex:"Every single vote will count in determining the outcome of the upcoming election.",exTr:"Yaklaşan seçimin sonucunu belirlemede her bir oy önemli olacak.",yz:3}],kl:[{en:"count on sb",tr:"birine güvenmek"},{en:"every vote counts",tr:"her oy önemlidir"},{en:"count the votes",tr:"oyları saymak"}]},
"discussion":{a:[{tr:"i. tartışma, görüşme, müzakere",ex:"The panel held a lengthy discussion about the economic impact of climate change on coastal cities.",exTr:"Panel, iklim değişikliğinin kıyı kentleri üzerindeki ekonomik etkisi hakkında uzun bir tartışma gerçekleştirdi."}],kl:[{en:"under discussion",tr:"görüşülmekte olan"},{en:"a discussion about sth",tr:"bir konuda tartışma"}]},
"linguistic":{a:[{tr:"s. dilsel, dilbilimsel",ex:"Researchers noted significant linguistic diversity among the indigenous communities living in that region.",exTr:"Araştırmacılar, o bölgede yaşayan yerli topluluklar arasında önemli bir dilsel çeşitlilik olduğunu belirtti."}],kl:[{en:"linguistic diversity",tr:"dilsel çeşitlilik"},{en:"linguistic ability",tr:"dil yeteneği"}]},
"mathematical":{a:[{tr:"s. matematiksel",ex:"Engineers used a complex mathematical model to predict how the bridge would respond to earthquakes.",exTr:"Mühendisler, köprünün depremlere nasıl tepki vereceğini tahmin etmek için karmaşık bir matematiksel model kullandı.",yz:4},{tr:"s. kesin, şüphe götürmez",ex:"The lawyer's closing argument had an almost mathematical precision that left the jury with no doubts.",exTr:"Avukatın kapanış konuşması, jüride hiçbir şüpheye yer bırakmayan neredeyse matematiksel bir kesinlik taşıyordu.",yz:1}],kl:[{en:"a mathematical model",tr:"matematiksel bir model"},{en:"mathematical precision",tr:"matematiksel kesinlik"}]},
