"genetically":{a:[{tr:"z. genetik olarak",ex:"Farmers increasingly plant genetically modified crops that resist drought and disease more effectively.",exTr:"Çiftçiler, kuraklığa ve hastalığa daha etkili biçimde dayanan genetiği değiştirilmiş ürünleri giderek daha çok ekiyor."}],kl:[{en:"genetically modified food",tr:"genetiği değiştirilmiş gıda"},{en:"genetically identical",tr:"genetik olarak özdeş"}]},
"grind":{a:[{tr:"f. öğütmek",ex:"Ancient communities used heavy stones to grind wheat into flour for making bread.",exTr:"Eski topluluklar, ekmek yapmak için buğdayı una öğütmede ağır taşlar kullanırdı.",yz:4},{tr:"i. angarya",ex:"After years of the same daily grind, she finally quit her office job to travel around the world.",exTr:"Yıllarca süren aynı günlük angaryanın ardından, dünyayı gezmek için sonunda ofis işinden istifa etti.",yz:1}],kl:[{en:"grind to a halt",tr:"durma noktasına gelmek"},{en:"grind coffee beans",tr:"kahve çekirdeği öğütmek"},{en:"the daily grind",tr:"günlük angarya"}]},
