"fluid":{a:[{tr:"i. sıvı, akışkan",ex:"Doctors recommend increasing fluid intake during hot weather to prevent dehydration and heat stroke.",exTr:"Doktorlar, sıcak havalarda su kaybını ve sıcak çarpmasını önlemek için sıvı alımını artırmayı öneriyor.",yz:4},{tr:"s. değişken, akıcı",ex:"The political situation in the region remains fluid, with alliances shifting almost every week.",exTr:"Bölgedeki siyasi durum, ittifakların neredeyse her hafta değişmesiyle değişken kalmaya devam ediyor.",yz:2}],kl:[{en:"body fluids",tr:"vücut sıvıları"},{en:"fluid intake",tr:"sıvı alımı"},{en:"a fluid situation",tr:"değişken bir durum"}]},
"freeze":{a:[{tr:"f. donmak, dondurmak",ex:"Scientists observed that certain species of frogs can freeze solid during winter and survive.",exTr:"Bilim insanları, bazı kurbağa türlerinin kışın tamamen donabildiğini ve hayatta kalabildiğini gözlemledi.",yz:4},{tr:"i. donma, dondurma",ex:"The sudden freeze overnight damaged much of the fruit crop across the valley.",exTr:"Gece yaşanan ani donma, vadi genelinde meyve ürününün büyük bölümüne zarar verdi.",yz:2}],kl:[{en:"freeze to death",tr:"donarak ölmek"},{en:"freeze assets",tr:"varlıkları dondurmak"},{en:"a wage freeze",tr:"ücretlerin dondurulması"}]},
"hinder":{a:[{tr:"f. engellemek, güçleştirmek, geciktirmek",ex:"Heavy snowfall continued to hinder rescue efforts in the mountainous region for days.",exTr:"Yoğun kar yağışı, dağlık bölgedeki kurtarma çalışmalarını günlerce engellemeye devam etti."}],es:"obstruct, hamper",kl:[{en:"hinder sb from sth",tr:"birini bir şeyden alıkoymak"},{en:"hinder progress",tr:"gelişmeyi engellemek"},{en:"hinder economic growth",tr:"ekonomik büyümeyi engellemek"}]},
"inevitable":{a:[{tr:"s. kaçınılmaz",ex:"Many economists now consider a global recession almost inevitable given current market conditions.",exTr:"Birçok ekonomist, mevcut piyasa koşulları göz önüne alındığında küresel bir durgunluğu artık neredeyse kaçınılmaz görüyor.",yz:4},{tr:"i. kaçınılmaz olay/durum",ex:"Despite years of preparation, the small village could not escape the inevitable when the flood finally arrived.",exTr:"Yıllarca süren hazırlıklara rağmen, küçük köy sel nihayet geldiğinde kaçınılmaz olanı önleyemedi.",yz:1}],es:"unavoidable, certain",kl:[{en:"it is inevitable that",tr:"kaçınılmazdır ki"},{en:"an inevitable consequence",tr:"kaçınılmaz bir sonuç"},{en:"accept the inevitable",tr:"kaçınılmazı kabullenmek"}]},
"investigation":{a:[{tr:"i. soruşturma, inceleme, araştırma",ex:"Police launched a thorough investigation into the causes of the devastating factory fire.",exTr:"Polis, yıkıcı fabrika yangınının nedenlerine ilişkin kapsamlı bir soruşturma başlattı."}],kl:[{en:"an investigation into sth",tr:"bir konuda soruşturma"},{en:"launch an investigation",tr:"soruşturma başlatmak"},{en:"under investigation",tr:"soruşturma altında"}]},
