"grammar":{a:[{tr:"i. dil bilgisi, gramer",ex:"Learning the grammar of a foreign language requires consistent practice and careful attention to detail.",exTr:"Yabancı bir dilin dil bilgisini öğrenmek, düzenli alıştırma ve ayrıntılara özen gerektirir."}],kl:[{en:"grammar rules",tr:"dil bilgisi kuralları"},{en:"a grammar mistake",tr:"dil bilgisi hatası"}]},
"independently":{a:[{tr:"z. bağımsız olarak, ayrı ayrı",ex:"Two research teams working independently reached remarkably similar conclusions about the ancient fossil.",exTr:"Birbirinden bağımsız çalışan iki araştırma ekibi, eski fosille ilgili şaşırtıcı derecede benzer sonuçlara ulaştı."}],kl:[{en:"work independently",tr:"bağımsız çalışmak"},{en:"independently of each other",tr:"birbirinden bağımsız olarak"}]},
