"speaking":{a:[{tr:"i. konuşma",ex:"Public speaking courses help students build confidence and express their ideas clearly in academic settings.",exTr:"Topluluk önünde konuşma dersleri, öğrencilerin özgüven kazanmasına ve akademik ortamlarda fikirlerini açıkça ifade etmesine yardımcı olur.",yz:3},{tr:"s. konuşan",ex:"English-speaking employees were asked to help translate documents for the newly arrived refugees.",exTr:"İngilizce konuşan çalışanlardan, yeni gelen mültecilerin belgelerini çevirmelerine yardımcı olmaları istendi.",yz:3}],kl:[{en:"generally speaking",tr:"genel olarak konuşursak"},{en:"strictly speaking",tr:"tam anlamıyla söylersek"},{en:"public speaking",tr:"topluluk önünde konuşma"}]},
