"theoretical":{a:[{tr:"s. kuramsal, teorik",ex:"Many engineering breakthroughs begin as a theoretical model long before any prototype is built.",exTr:"Pek çok mühendislik atılımı, herhangi bir prototip üretilmeden çok önce kuramsal bir model olarak başlar."}],kl:[{en:"a theoretical framework",tr:"kuramsal çerçeve"},{en:"a theoretical approach",tr:"kuramsal bir yaklaşım"}]},
