"dealing":{a:[{tr:"i. muamele, davranış tarzı",ex:"Fair dealing with customers builds long-term trust and strengthens a company's reputation in the market.",exTr:"Müşterilerle dürüst ilişki, uzun vadeli güven oluşturur ve şirketin piyasadaki itibarını güçlendirir.",yz:3},{tr:"i. ticaret, alışveriş",ex:"The company's dealing in second-hand electronics generated significant profit last year.",exTr:"Şirketin ikinci el elektronik ticareti geçen yıl önemli kâr sağladı.",yz:3}],kl:[{en:"dealings with sb",tr:"biriyle olan ilişkiler"},{en:"drug dealing",tr:"uyuşturucu ticareti"}]},
