"extended":{a:[{tr:"s. uzatılmış, genişletilmiş; uzun süreli",ex:"Following the sudden schedule changes, the airline offered passengers an extended refund period.",exTr:"Ani sefer değişikliklerinin ardından, havayolu şirketi yolculara uzatılmış bir iade süresi tanıdı."}],kl:[{en:"an extended period",tr:"uzun bir dönem"},{en:"the extended family",tr:"geniş aile"}]},
"gut":{a:[{tr:"i. bağırsak",ex:"Bacteria living in the human gut play a crucial role in digestion and immunity.",exTr:"İnsan bağırsağında yaşayan bakteriler, sindirim ve bağışıklıkta hayati bir rol oynar.",yz:4},{tr:"f. içini boşaltmak, tahrip etmek",ex:"The fire completely gutted the historic theater, leaving only its outer stone walls standing.",exTr:"Yangın, tarihi tiyatronun içini tamamen boşalttı; yalnızca dış taş duvarları ayakta kaldı.",yz:1}],kl:[{en:"a gut feeling",tr:"içgüdüsel his, içine doğan his"},{en:"gut bacteria",tr:"bağırsak bakterileri"}]},
"know-how":{a:[{tr:"i. teknik bilgi, uzmanlık, beceri",ex:"Developing countries often lack the technical know-how required to build advanced manufacturing industries.",exTr:"Gelişmekte olan ülkeler, ileri imalat sanayileri kurmak için gereken teknik bilgiden çoğu zaman yoksundur."}],kl:[{en:"technical know-how",tr:"teknik bilgi birikimi, uzmanlık"},{en:"have the know-how",tr:"işin nasıl yapılacağını bilmek"}]},
"leg":{a:[{tr:"i. bacak",ex:"The injured player was unable to put any weight on his left leg after the collision.",exTr:"Yaralı oyuncu, çarpışmadan sonra sol bacağına hiç ağırlık veremedi.",yz:3},{tr:"i. (yolculuk/yarış) etap",ex:"The final leg of the marathon route climbed steeply through the old town's narrow streets.",exTr:"Maratonun son etabı, eski şehrin dar sokaklarından geçerek dik biçimde yükseliyordu.",yz:2}],kl:[{en:"the last leg of sth",tr:"bir yolculuğun son etabı"},{en:"stretch your legs",tr:"biraz yürümek, bacakları açmak"}]},
