"moment":{a:[{tr:"i. an, lahza",ex:"Historians consider the fall of the Berlin Wall a defining moment of the twentieth century.",exTr:"Tarihçiler, Berlin Duvarı'nın yıkılışını yirminci yüzyılın belirleyici anlarından biri olarak görür."}],kl:[{en:"at the moment",tr:"şu anda"},{en:"for a moment",tr:"bir anlığına"},{en:"at any moment",tr:"her an"}]},
