"problematic":{a:[{tr:"s. sorunlu, tartışmalı",ex:"Relying solely on fossil fuels has become increasingly problematic as climate concerns grow.",exTr:"Sadece fosil yakıtlara güvenmek, iklim endişeleri arttıkça giderek daha sorunlu hale geldi."}],kl:[{en:"prove problematic",tr:"sorunlu çıkmak"},{en:"particularly problematic",tr:"özellikle sorunlu"}]},
