"round":{a:[{tr:"i. tur, aşama, raunt",ex:"The negotiations entered a third round without producing any agreement.",exTr:"Müzakereler, herhangi bir anlaşma sağlanmadan üçüncü tura girdi.",yz:4},{tr:"s. yuvarlak",ex:"Ancient astronomers had already argued that the Earth was round.",exTr:"Antik dönem gökbilimcileri, Dünya'nın yuvarlak olduğunu çoktan öne sürmüştü.",yz:3},{tr:"f. (sayıyı) yuvarlamak",ex:"Statisticians typically round large figures to the nearest thousand for easier comparison.",exTr:"İstatistikçiler, karşılaştırmayı kolaylaştırmak için büyük rakamları genellikle en yakın bine yuvarlar.",yz:2},{tr:"z./e. (BrE) etrafında, çevresinde",ex:"The children sat round the fire and listened to the old stories.",exTr:"Çocuklar ateşin etrafında oturup eski hikâyeleri dinledi.",yz:1}],kl:[{en:"all year round",tr:"yıl boyunca"},{en:"a new round of talks",tr:"yeni bir görüşme turu"}]},
