"storm":{a:[{tr:"i. fırtına",ex:"The tropical storm destroyed hundreds of homes and left thousands of people without electricity.",exTr:"Tropikal fırtına yüzlerce evi yıktı ve binlerce insanı elektriksiz bıraktı.",yz:4},{tr:"f. hücum etmek; öfkeyle dalmak",ex:"Furious protesters tried to storm the government building before police pushed them back with barricades.",exTr:"Öfkeli göstericiler, polis onları barikatlarla geri püskürtmeden önce hükûmet binasına hücum etmeye çalıştı.",yz:1}],kl:[{en:"weather the storm",tr:"fırtınayı atlatmak"},{en:"take sth by storm",tr:"bir yeri kasıp kavurmak"}]},
